"""Manual source-cover audit: dates, sessions, semesters and exam format."""
from html import escape
from urllib.parse import quote

# Every path is the original exam with the cover, not a reconstructed solution.
COVERS = [
 ('2022 · קיץ','07/10/2022','2022/File_1_689156_07102022_0.pdf','06/11/2022','ללא תאריך/c22b - מקודד.docx.pdf','12 שאלות ברירה ושאלה פתוחה בכל מועד'),
 ('2023 · סמסטר ב','07/07/2023','2023/689156_07072023_0 (6).pdf','08/08/2023','2023/689156_08082023_0 (1).pdf','10 שאלות ברירה בכל מועד'),
 ('2024 · סמסטר ב','31/05/2024','2024/689156_31052024_0.docx (2).pdf','04/07/2024','2024/689156_04072024_0 (2).pdf','10 שאלות ברירה בכל מועד'),
 ('2024 · קיץ','17/09/2024','2024/689156_04_17092024_0 2 (1).pdf','20/10/2024','2024/689156_04_20102024_0 3.pdf','10 שאלות ברירה בכל מועד'),
 ('2025 · סמסטר ב','21/07/2025','2025/689156_21072025_0 (5).pdf','21/08/2025','2025/689156_21082025_0 (6).pdf','10 שאלות ברירה בכל מועד'),
 ('2025 · קיץ','05/10/2025','2025/689156_05102025_0 (3).pdf','02/11/2025','2025/689156_02112025_0 (5).pdf','10 שאלות ברירה בכל מועד'),
 ('2026 · סמסטר ב','12/07/2026','2026/689156_01_12072026_0 (2).pdf','09/08/2026','2026/File_0_689156_01_09082026_0.pdf','10 שאלות ברירה בכל מועד'),
]

def cover_page(pairs, root):
    assert [(label,a,b) for label,a,_,b,_,_ in COVERS] == [(p[0],p[1],p[2]) for p in pairs]
    for _,_,a,_,b,_ in COVERS:
        assert (root/a).is_file() and (root/b).is_file()
    body='''<p class="study-intro">נבדק מול העמוד הראשון של כל אחד מ-14 השאלונים המקוריים: תאריך, מועד, סמסטר וקורס. הקישורים מובילים למסמכי המקור, הכוללים גם את כל השאלות; פתיחתם אינה מבחן מעורבב.</p>
<p>שבעת הזוגות הם מועד א׳ ומועד ב׳ של אותו סמסטר וקורס 689156. תיוג זה אינו מוכיח שתוכן השאלות יחזור במועד ב׳ הבא.</p><div class="study-table"><table><thead><tr><th>סמסטר</th><th>מועד א׳ — דף מקור</th><th>מועד ב׳ — דף מקור</th><th>פורמט</th></tr></thead><tbody>'''
    for label,a,ap,b,bp,fmt in COVERS:
        link=lambda p:quote(p,safe='/')+'#page=1'
        body+=f'<tr><td>{escape(label)}</td><td><a href="{link(ap)}">{a}</a></td><td><a href="{link(bp)}">{b}</a></td><td>{escape(fmt)}</td></tr>'
    return body+'''</tbody></table></div><h2>הבחנות שמשפיעות על הניתוח</h2>
<p>בשנת 2022 כל שאלון כלל גם שאלה פתוחה, שלא נספרה בניתוח הברירה. בסימולציה הממוקדת 12 שאלות הברירה של כל מועד מנורמלות ל-10 לפני שמחשבים תמהיל; אין בכך הוכחה שמבנה הבחינה ההיא שקול למבנה הנוכחי.</p>
<p>המסמך של מועד ב׳ מ-06/11/2022 שמור בתיקיית ״ללא תאריך״, אך דף השער שלו מציין את התאריך, הסמסטר ומועד ב׳ במפורש. הקובץ המסודר הנוסף מאותו תאריך אינו מציג דף שער, ולכן אינו המקור לקביעת המועד.</p>
<p>24/11/2024 ו-30/11/2025 הם מועדים מיוחדים, ולא הוגדרו כמועדי ב׳ בזוגות; הם עדיין נכללים בספירת כלל המועדים. <a href="2024/689156_24112024_0%20%282%29.pdf#page=1">דף השער של נובמבר 2024</a> · <a href="2025/689156_30112025_0%20%283%29.pdf#page=1">דף השער של נובמבר 2025</a>.</p>
<p>בדיקה זו מאמתת את שיוך המועדים בלבד. תיוג נושאים ומיומנויות הוא ניתוח נפרד, ותוצאות עתידיות אינן ידועות.</p><p><a href="confidence.html">חזרה לשיטת הדירוג</a> · <a href="analysis.html">ניתוח א׳/ב׳</a></p>'''
